const agoText=ms=>{const s=Math.max(0,Math.round(ms/1000));if(s<10)return 'just now';if(s<60)return Math.floor(s/10)*10+' seconds ago';const m=Math.floor(s/60);if(m<60)return m===1?'1 minute ago':m+' minutes ago';const h=Math.floor(m/60);return h===1?'1 hour ago':h+' hours ago'};
const lastUpdated=()=>'Last updated '+agoText(Date.now()-connectionLostAt);
const connectionReason=()=>sampleConnection==='Live'?'':sampleConnection==='Offline'?'LGcode is offline. This works again when the connection returns.':sampleConnection==='Connecting'?'Connecting to LGcode. This works once the page connects.':'Reconnecting to LGcode. This works again when the connection returns.';
function setConnection(next,lostAgo=0){clearTimeout(offlineTimer);if(next!=='Live'&&(sampleConnection==='Live'||lostAgo))connectionLostAt=Date.now()-lostAgo;sampleConnection=next;if(['Reconnecting','Connecting'].includes(next))offlineTimer=setTimeout(()=>{if(['Reconnecting','Connecting'].includes(sampleConnection)){sampleConnection='Offline';render()}},Math.max(0,offlineAfter-(Date.now()-connectionLostAt)));render()}
function renderConnection(){const c=sampleConnection,stale=staleConnection(),state=$('#connection-state'),updated=stale?lastUpdated():'';$('#connection-status').className='connection-status'+(c==='Live'?'':c==='Offline'?' is-offline':' is-waiting');$('#connection-dot').className='dot '+(c==='Live'?'':c==='Offline'?'error':'wait');if(state.textContent!==c)state.textContent=c;$('#connection-updated').textContent=updated;$('#connection-status').title=stale?updated+'. '+connectionReason():'';$('#retry-connection').hidden=!stale;$('#attention-toggle').classList.toggle('stale',stale);$('#attention-toggle').title=stale?'Count from the last update, '+agoText(Date.now()-connectionLostAt):''}
