const connectionGated='#new-project,[data-add-project],[data-home-new-project],[data-new-on-machine],#new-terminal,#refresh-alerts,#load-more-alerts';
function gateConnection(){const why=connectionReason();document.querySelectorAll('[data-connection-title]').forEach(el=>{const t=el.dataset.connectionTitle;if(t)el.title=t;else el.removeAttribute('title');delete el.dataset.connectionTitle});document.querySelectorAll(connectionGated).forEach(el=>el.disabled=!!why);if(!why)return;document.querySelectorAll('.app button:disabled,.app input:disabled,.app select:disabled,.app textarea:disabled,dialog button:disabled,dialog input:disabled,dialog select:disabled,dialog textarea:disabled').forEach(el=>{if(el.matches('#home-clear-filters'))return;el.dataset.connectionTitle=el.title||'';el.title=why})}
let gateQueued=false;new MutationObserver(()=>{if(sampleConnection==='Live'||gateQueued)return;gateQueued=true;queueMicrotask(()=>{gateQueued=false;gateConnection()})}).observe(document.body,{childList:true,subtree:true});
