// STATUS-3: questions, approvals, merges, and failed starts share one request block. It spans the thread, and its left rule and label take the kind's colour.
function requestBlock(kind,{id='',label,title='',body,open=false,aria=''}){return `<section class="request is-${kind}${open?' is-open':''}" ${id?`id="${id}" tabindex="-1"`:''} aria-label="${esc(aria||title||label)}"><p class="request-label">${label}</p>${title?`<h2>${esc(title)}</h2>`:''}${body}</section>`}
// HOME-8: an approval names its command and folder on labelled lines. Identifiers and the raw input sit under Details.
const inputFields=[['command','Command'],['cwd','Folder'],['path','File'],['url','Address']],inputText=v=>Array.isArray(v)?v.join(' '):String(v);
