function boardView(){if(!p().sprints.length&&p().mocks&&!p().mocks.approvedAt)return emptyState('No sprints until you approve the mocks.',`<button class="primary" data-open-mocks="${p().id}">Open the mocks</button>`);if(!p().sprints.length)return emptyState('No sprints yet.',`<button class="primary" data-focus-lead>Talk to ${esc(p().lead.name)}</button>`);
 const columns=[['planned','Planned'],['active','In progress'],['review','Review'],['done','Done']];
 return `<div class="board-intro"><span>The project plan, from the next sprint to verified work.</span><button class="inline-link" data-focus-lead>Talk to ${esc(p().lead.name)} ${icon('arrow')}</button></div><div class="kanban">${columns.map(([id,label])=>{const values=p().sprints.filter(s=>sprintState(s)===id);return `<section class="kanban-column" aria-label="${label}"><h2 class="column-heading ${id}"><span class="dot"></span>${label}<small>${values.length}</small></h2>${values.map(s=>{const tasks=sprintTasks(s),done=tasks.filter(t=>t.state==='done').length,rs=projectRequests().filter(r=>r.sprintId===s.id),dependency=s.needs.map(n=>p().sprints.find(x=>x.id===n)).find(n=>n.completion!=='merged');return `<button class="sprint-card" data-sprint="${s.id}"><span class="sprint-id">${s.label} · ${s.phase}</span><h3>${esc(s.name)}</h3><p>${esc(s.goal)}</p><span class="sprint-meta"><span>${esc([...new Set([s.owner,...tasks.map(t=>t.owner)])].map(id=>findAgent(id).name).join(', '))}</span><span>${done}/${tasks.length} tasks</span></span><span class="sprint-progress" aria-hidden="true"><span style="--progress:${tasks.length?done/tasks.length*100:0}%"></span></span>${rs.length?'<span class="sprint-note"><span class="dot wait"></span>Needs answer</span>':dependency?`<span class="sprint-dependency">Waiting on ${dependency.label}</span>`:s.completion==='merged'?'<span class="sprint-dependency">Verified · Merged to main</span>':''}</button>`}).join('')}${values.length?'':'<p class="column-empty">No sprints here</p>'}</section>`}).join('')}</div>`;
}
function sprintView(){const s=p().sprints.find(x=>x.id===state.sprintId),tasks=sprintTasks(s),rs=projectRequests().filter(r=>r.sprintId===s.id);return `<button class="inline-link back-link" data-board="${p().id}">${icon('arrow-left')}Project board</button><div class="sprint-detail"><div><p class="detail-summary">${esc(s.goal)}</p><section class="detail-section"><div class="section-heading"><h2>Plan tasks</h2>${s.completion==='merged'?'':`<button class="secondary dense" id="add-task">${icon('plus')}Add task</button>`}</div>${taskTable(tasks)}</section>${rs.length?`<section class="detail-section"><h2>Needs answer</h2>${rs.map(requestLink).join('')}</section>`:''}${s.completion==='merged'?`<section class="detail-section"><h2>Completion evidence</h2><p class="muted">${esc(s.evidence)} · Release status is tracked separately.</p></section>`:''}</div><aside class="detail-sidebar" aria-label="Sprint context"><dl><div><dt>Owner</dt><dd><button class="inline-link" data-talk-agent="${s.owner}">${esc(findAgent(s.owner).name)}</button></dd></div><div><dt>Phase</dt><dd>${s.phase}</dd></div><div><dt>Team</dt><dd>${[...new Set(tasks.map(t=>p().teams.find(x=>x.id===t.teamId)?.name))].map(esc).join(', ')||'Not assigned'}</dd></div><div><dt>Depends on</dt><dd>${s.needs.length?s.needs.map(id=>{const dep=p().sprints.find(x=>x.id===id);return `<button class="inline-link" data-sprint="${id}">${dep.label} · ${esc(dep.name)}</button>`}).join('<br>'):'No dependencies'}</dd></div><div><dt>Plan</dt><dd>${esc(p().name)} / ${s.label}</dd></div></dl></aside></div>`}
function taskView(){const t=p().tasks.find(x=>x.id===state.taskId),s=p().sprints.find(x=>x.id===t.sprintId),w=workspaces.find(x=>x.id===t.workspace),r=requests.find(x=>x.taskId===t.id),owner=findAgent(t.owner).name,story=taskStories[t.id]||{summary:s.goal,done:['Meets the goal of '+s.label,'Reviewed by the team lead'],activity:[{title:t.addedByOwner?'Added by you':'Assigned by '+p().lead.name,detail:owner+' owns '+t.id+'.'}]},timeline=`<ol class="task-timeline">${story.activity.map(step=>{const open=step.question&&requests.find(x=>x.id===step.question)?.status==='open',shown=step.question?(open?step.open:step.answered):step;return `<li class="${open?'waiting':''}"><strong>${esc(shown.title)}</strong><small>${esc(shown.detail)}</small></li>`}).join('')}</ol>`;return `<button class="inline-link back-link" data-sprint="${s.id}">${icon('arrow-left')}${s.label} · ${esc(s.name)}</button><div class="sprint-detail"><div><p class="detail-summary">${esc(story.summary)}</p>${r?.status==='open'?requestLink(r):r?'<p class="request-result">Owner direction recorded. This request is resolved.</p>':''}<section class="detail-section"><h2>Done when</h2><ul class="task-done">${story.done.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="detail-section"><h2>Activity</h2>${timeline}</section>${w.files.length?`<section class="detail-section"><h2>Changed files</h2><div class="run-files">${w.files.map(f=>`<button class="inline-link" data-inspect-file="${esc(f)}" data-inspect-workspace="${w.id}">${esc(f)} ${icon('arrow')}</button>`).join('')}</div></section>`:''}<div class="request-actions"><button class="primary" data-talk-agent="${t.owner}">Talk to ${esc(owner)}</button><button class="inline-link" data-show-changes="${t.workspace}" data-changes-team="${t.teamId}">View changes ${icon('arrow')}</button></div></div><aside class="detail-sidebar" aria-label="Assignment context"><dl><div><dt>Task</dt><dd>${t.id}</dd></div><div><dt>Status</dt><dd>${taskState(t)}</dd></div><div><dt>Owner</dt><dd>${esc(owner)}</dd></div><div><dt>Team</dt><dd>${esc(p().teams.find(x=>x.id===t.teamId).name)}</dd></div><div><dt>Assigned branch</dt><dd><code>${esc(w.branch)}</code></dd></div><div><dt>Worktree</dt><dd><code>${esc(w.path)}</code></dd></div></dl></aside></div>`}
function repositoriesView(){return `<p class="detail-summary">Repositories connected from your workspace. Start a project inside a repository to talk through what you want to build.</p><table class="repos-table"><thead><tr><th>Repository</th><th class="hide-small">Projects</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${repositories.map(r=>`<tr><td><button class="inline-link" data-open-repo="${r.id}">${esc(r.name)}</button><span class="repo-path">${esc(r.path)}</span></td><td class="hide-small">${projects.filter(x=>x.repoId===r.id).length} projects</td><td><button class="secondary dense" data-add-project="${r.id}">${icon('plus')}New project</button></td></tr>`).join('')}</tbody></table>`}
