 const project=p(),a=recipient(),repositoriesPage=['repositories','repository','alerts','settings','machines','subscriptions'].includes(state.view),repoPage=state.view==='repository',t=team(),s=project.sprints.find(x=>x.id===state.sprintId),task=project.tasks.find(x=>x.id===state.taskId);
