 $('#view-title').textContent=title;
 $('#participants').innerHTML=state.view==='workspace-settings'?`${esc(p().name)} · Assigned worktree`:['terminal','source-control'].includes(state.view)?`${esc(machineFor().name)} · ${esc(workspace().branch)} · ${esc(workspace().path)}`:['alerts','settings','machines','subscriptions'].includes(state.view)?'':repoPage?`${projects.filter(x=>x.repoId===state.repoId).length} projects · One lead per project`:repositoriesPage?'Available on your computer':state.view==='board'?`Project board · ${plural(project.sprints.length,'sprint')} · ${esc(project.lead.name)} leads · Assigned to ${esc(machineFor(project).name)}`:state.view==='sprint'?`${s.label} · ${s.phase}`:state.view==='task'?`${task.id} · ${taskState(task)}`:state.tab!=='chat'?`${esc(t.name)} · ${esc(project.name)}`:state.agentId===project.lead.id?`Project lead · ${esc(project.name)}${projectRequests().length?` · <span style="color:var(--color-warn)">${plural(projectRequests().length,'decision')} waiting</span>`:''}`:state.agentId?`${esc(a.role)} · ${esc(t.name)}`:`${esc(t.agents[0].name)} leads · ${t.agents.length} agents`;
 $('#conversation-header').classList.toggle('has-team-tabs',state.view==='chat'&&!!state.teamId&&!state.agentId);
