function renderContext(){const active=workspace(),assigned=assignedWorkspace(),r=repo(),query=($('#workspace-search')?.value||'').trim().toLowerCase(),inRepo=workspaces.filter(w=>w.repoId===state.repoId),isMain=w=>w.path===repositoryLocations.get(w.repoId+'/'+w.machineId);
 const label=w=>{if(w.parentId){const owner=projects.find(x=>x.teams.some(t=>t.workspace===w.id));return owner?.teams.find(t=>t.workspace===w.id)?.name||w.owner}return isMain(w)?'Main checkout':projects.find(x=>x.workspace===w.id)?.name||w.owner};
 const roots=inRepo.filter(w=>!w.parentId).sort((x,y)=>isMain(y)-isMain(x)||(y.machineId===thisMachine.id)-(x.machineId===thisMachine.id)),ordered=roots.flatMap(w=>[[w,0],...inRepo.filter(c=>c.parentId===w.id).map(c=>[c,1])]);
 const row=([w,depth])=>{const name=label(w),machine=machineItems.find(m=>m.id===w.machineId)?.name||'',text=[name,w.branch,machine].join(' ').toLowerCase();if(query&&!text.includes(query))return '';return `<button class="workspace-option depth-${depth}" data-workspace="${w.id}" aria-pressed="${w.id===active.id}" title="${esc(w.branch+' · '+w.path+' · '+w.activity)}"><span class="ws-label">${esc(name)}</span><code class="tail"><bdi>${esc(w.branch)}</bdi></code>${w.id===assigned.id?'<small class="ws-tag">Assigned</small>':''}<small class="ws-machine">${esc(machine)}</small>${w.id===active.id?icon('check','check-icon'):'<span class="check-icon"></span>'}</button>`};
 $('#workspace-options').innerHTML=ordered.map(row).join('')||`<p class="op-caption">No worktree matches “${esc(query)}”.</p>`}
