function restoreConversationScroll(){if(!isChat())return;const scroller=conversationScroller(),saved=chatPositions.get(conversationKey());scroller.scrollTop=saved===undefined||saved==='end'?scroller.scrollHeight:saved;updateLatest()}
function updateLatest(){const button=$('#latest-button');if(!isChat()||$('#composer-wrap').hidden){button.hidden=true;return}const scroller=conversationScroller(),bottom=scroller.getBoundingClientRect().bottom,below=[...scroller.querySelectorAll('.request.is-open,.request-link')].filter(e=>e.getBoundingClientRect().top>=bottom-8).length;button.hidden=scroller.scrollHeight-scroller.scrollTop-scroller.clientHeight<=24;button.textContent=below?`${below} ${below===1?'request':'requests'} below`:'Latest'}
function setLeadPanel(open){remember();leadPanelOpen=open;render();if(open)$('#message-input').focus();else $('#lead-toggle').focus()}
