function prepareProjectForm(repoId,locked=false){$('#project-form').reset();$('#project-repo').innerHTML=`<optgroup label="In your workspace folder, ${esc(thisMachine.workspaceFolder)}">${repositories.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</optgroup><optgroup label="Start fresh"><option value="__new" ${locked?'disabled':''}>New repository…</option></optgroup>`;$('#project-repo').value=repoId;$('#project-repo').disabled=locked;$('#project-error').hidden=true;syncNewRepository();renderProjectMachines();renderProjectLeads();updateProjectLocation()}
