function updateProjectLocation(){const plan=projectWorkspacePlan(),machine=machineItems.find(m=>m.id===plan.machineId);$('#project-submit').disabled=!canOperate()||!plan.path||machine?.status!=='Online';$('#project-location-preview').textContent=plan.path?(machine?.name||'Machine')+' · '+(plan.fresh?'New repository':$('#project-worktree').checked?'New worktree':'Main checkout')+' · '+plan.branch+' · '+plan.path:plan.fresh?'Name the repository to see where it will go.':'No available machine has this repository.'}
