// HOME-6: a closed request says what happened, Allowed, Denied, Answered, or Merged, and homeClosedAt says when.
function homeStatus(item){if(item.status==='open')return item.request?.holder==='lead'||item.permission?.holder==='lead'?'Held elsewhere':item.permission?.answerState==='unconfirmed'?'Answer unconfirmed':'Open';if(item.status==='cancelled')return 'Cancelled';return item.permission?(item.permission.answer==='Denied'?'Denied':'Allowed'):item.merge?'Merged':'Answered'}
