function homeMatch(project,agentId,text){const h=homeState;return (h.repo==='all'||project.repoId===h.repo)&&(h.project==='all'||project.id===h.project)&&(h.machine==='all'||machineFor(project).id===h.machine)&&(h.agent==='all'||(agentId?agentId===h.agent:agents(project).some(a=>a.id===h.agent)))&&text.toLowerCase().includes(h.search.trim().toLowerCase())}
