const homeOrder=(a,b)=>homeState.sort==='newest'?Number(b.status==='open')-Number(a.status==='open')||Number(b.kind==='Failed start')-Number(a.kind==='Failed start')||(attentionSince(b)??H.clock)-(attentionSince(a)??H.clock):byAttention(a,b);
function filteredHomeItems(){const kinds=homeKinds[homeState.tab];return homeItems().filter(i=>(homeState.tab!=='attention'||i.status==='open')&&(!kinds||kinds.includes(i.kind))&&homeMatch(i.project,i.agentId,[i.title,i.kind,i.task,i.permission?.input?.command,i.project.name,repoFor(i.project).name,findAgent(i.agentId,i.project)?.name,machineFor(i.project).name,homeStatus(i)].join(' '))).sort(homeOrder)}
const repoFor=project=>repositories.find(r=>r.id===project.repoId);
function openHome(tab=null,clear=false){if(clear)Object.assign(homeState,{repo:'all',project:'all',agent:'all',machine:'all',status:'all',search:'',selected:null});if(tab&&homeState.tab!==tab){homeState.tab=tab;homeState.status='all';homeState.selected=null;homeState.filtersOpen=false}$('#attention-menu').hidePopover();go({view:'home',teamId:null,agentId:p().lead.id,tab:'chat',sprintId:null,taskId:null})}
function homeSelect(id){homeState.selected=homeState.selected===id?null:id;renderHomeBody();if(homeState.selected)$('#home-detail')?.classList.add('row-opening');document.querySelector(`[data-home-item="${CSS.escape(id)}"]`)?.focus({preventScroll:true})}
const homeFiltered=()=>['repo','project','agent','machine','status'].some(k=>homeState[k]!=='all')||!!homeState.search;
const homeFilterFields=[['repo','Repository','All repositories'],['project','Project','All projects'],['agent','Agent','All agents'],['machine','Machine','All machines'],['status','Status','Any status']];
function homeFilterOptions(){const h=homeState,projectsInRepo=projects.filter(p=>h.repo==='all'||p.repoId===h.repo);return {repo:repositories.map(r=>[r.id,r.name]),project:projectsInRepo.map(p=>[p.id,p.name]),agent:projectsInRepo.filter(p=>h.project==='all'||p.id===h.project).flatMap(agents).map(a=>[a.id,a.name]),machine:machineItems.map(m=>[m.id,m.name]),status:h.tab==='projects'?[['Needs attention','Needs attention'],['Working','Working'],['Planning','Planning']]:[]}}
// HOME-4: Home shows one search field and one Filter button. The chosen filters show as chips that remove themselves, and Clear filters appears only when something is set.
function homeChips(){if(!homeFiltered())return '';const h=homeState,options=homeFilterOptions();return `<div class="home-chips" aria-label="Active filters">${homeFilterFields.filter(([f])=>h[f]!=='all').map(([f,label])=>{const name=options[f].find(([id])=>id===h[f])?.[1]||h[f];return `<button class="home-chip" data-home-remove-filter="${f}" aria-label="Remove the ${label.toLowerCase()} filter, ${esc(name)}"><span>${label}: ${esc(name)}</span>${icon('x')}</button>`}).join('')}<button class="secondary dense" id="home-clear-filters">Clear filters</button></div>`}
