function setHomeFiltersOpen(open,focus=false){homeState.filtersOpen=open;const menu=$('#home-filter-menu'),toggle=$('#home-filter-toggle');if(!menu)return;menu.hidden=!open;toggle.setAttribute('aria-expanded',open);if(focus)(open?menu.querySelector('select'):toggle)?.focus({preventScroll:true})}
function homeSourceLink(item){return item.merge?`data-inspect-merge="${esc(item.merge.id)}"`:item.request?`data-open-request="${esc(item.request.id)}"`:item.permission?`data-open-permission="${esc(item.permission.id)}"`:`data-alert-agent="${esc(item.agentId)}"`}
function homeMergeDetail(w){const g=gitState(w),target=integrationTarget(w),ready=gitCanWrite(w)&&!w.files.length&&!g.conflicts.size&&!g.incoming&&g.pending>0&&!target.files.length&&!gitState(target).conflicts.size;return requestBlock('merge',{label:'Merge',title:g.pending?'Review merge to '+target.branch:'Merged',open:g.pending>0,body:`<p class="merge-route"><code>${esc(w.branch)}</code> ${icon('arrow')}<span class="sr-only">into</span> <code>${esc(target.branch)}</code></p><p>${g.pending?plural(g.pending,'commit')+' awaiting your review.':'Merged into '+esc(g.lastMerge)+'.'}</p><ul>${g.commits.map(c=>`<li><strong>${esc(c.title)}</strong><small>${c.files.map(esc).join(', ')}</small></li>`).join('')}</ul>${g.pending?`<div class="request-actions"><button class="primary" data-home-merge="${esc(w.id)}" ${ready?'':'disabled'}>Review and approve</button></div>${ready?'':'<p class="op-warning">Resolve pending changes, conflicts, or incoming updates before merging.</p>'}`:''}`})}
// HOME-7: the expanded row starts with the request itself. The row above already names the agent, the project, and the title, so the panel has no header and no close button. The footer names the machine and the worktree.
function homeDetail(item){if(!item)return emptyState('No matching requests.','','home-empty-detail');const project=item.project,a=findAgent(item.agentId,project),m=machineFor(project),agentTeam=project.teams.find(t=>t.agents.some(a=>a.id===item.agentId)),w=workspaces.find(w=>w.id===agentTeam?.workspace)||projectWorkspace(project);
 return `${item.merge?homeMergeDetail(item.merge):item.request?decision(item.request,project):item.permission?permissionView(item.permission):requestBlock('failed',{label:'Failed start',title:item.title,open:true,aria:'Failed start',body:failureRemedy(a,project)})}<footer class="home-detail-footer"><button class="inline-link" ${homeSourceLink(item)}>${item.merge?'Review in Git':'Open '+esc(a.name)+'’s thread'} ${icon('arrow')}</button><button class="inline-link" data-project="${esc(project.id)}">Project board ${icon('arrow')}</button><span class="home-detail-context">${esc(m.name)} · <code>${esc(w?.branch||projectWorkspace(project).branch)}</code></span></footer>`}
function homeEmpty(){const h=homeState;if(homeFiltered())return emptyState('No matching requests.','<button class="secondary dense" data-home-clear>Clear filters</button>','home-empty');if(h.tab==='questions')return emptyState('No questions yet.','','home-empty');if(h.tab==='approvals')return emptyState('No approvals yet.','','home-empty');const working=projects.flatMap(agents).filter(a=>runtimeFor(a.id).state!=='stopped'&&agentProject(a.id).tasks.some(t=>t.owner===a.id&&['active','review'].includes(t.state))).length,active=projects.filter(project=>project.sprints.length).length;return `<div class="home-empty"><h2>Nothing needs you</h2>${projects.length?`<p>${working} ${working===1?'agent is':'agents are'} working across ${active} ${active===1?'project':'projects'}. <button class="inline-link" data-home-tab="projects">All projects ${icon('arrow')}</button></p>`:''}</div>`}
