document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.newOnMachine){showNewProject();const available=repositories.find(r=>repositoryLocations.has(r.id+'/'+d.newOnMachine));if(available){$('#project-repo').value=available.id;renderProjectMachines()}$('#project-machine').value=d.newOnMachine;updateProjectLocation();if(!available){$('#project-error').textContent='No repository is connected on this machine. Connect a repository here before starting a project.';$('#project-error').hidden=false}}if(b.id==='home-link')openHome();if(b.id==='attention-home')openHome('attention',true);if(d.homeTab){openHome(d.homeTab);$('#home-tab-'+d.homeTab)?.focus({preventScroll:true})}if(d.inspectMerge){const w=workspaces.find(w=>w.id===d.inspectMerge);openGit(w.id,ownerProject(w).id)}if(d.homeMerge){const w=workspaces.find(w=>w.id===d.homeMerge);openMergeReview(w)}if(d.homeItem)homeSelect(d.homeItem);if(d.homeProject)openBoard(d.homeProject);if(d.projectInbox){openHome('attention',true);homeState.project=d.projectInbox;render()}if(b.id==='home-clear-filters'||d.homeClear!==undefined){Object.assign(homeState,{repo:'all',project:'all',agent:'all',machine:'all',status:'all',search:'',selected:null});render();$('#home-search')?.focus({preventScroll:true})}if(d.homeRemoveFilter){homeState[d.homeRemoveFilter]='all';if(d.homeRemoveFilter==='repo'){homeState.project='all';homeState.agent='all'}if(d.homeRemoveFilter==='project')homeState.agent='all';homeState.selected=null;render();($('.home-chip')||$('#home-filter-toggle'))?.focus({preventScroll:true})}if(d.homeAnswered!==undefined){homeState.answeredOpen=!homeState.answeredOpen;renderHomeBody();$('[data-home-answered]')?.focus({preventScroll:true})}});
