$('#data-source').textContent=H.source==='prod'?'Showing the export from '+H.exportedAt+'.':H.source==='first'?'Showing a first run, from design/data/first.':'Showing the '+(heavySample?'heavy':'small')+' sample, from design/data/'+H.source+'.';
{const from=new URLSearchParams(location.search);if(from.has('from')){const back=$('#back-to-setup');back.hidden=false;back.href='?sample=first'+(from.get('setup')?'&setup='+encodeURIComponent(from.get('setup')):'')}}

// First run. Each page does one job. Nothing is asked until the owner has seen what LGcode found.
let setupPage=H.setup.step,setupScan=null,setupScanning=false,setupChangingFolder=false,setupFormReady=false,setupNameEdited=false;
const setupSearch=()=>{const scenario=new URLSearchParams(location.search).get('setup');return scenario?'&setup='+encodeURIComponent(scenario):''};
function setupStepMark(n){return `<p class="setup-step">Step ${n} of 3</p>`}
function setupWelcome(){return `<h1 id="setup-title" tabindex="-1">LGcode</h1><p class="setup-lede">Runs teams of coding agents on your machines, and shows you where to look.</p><dl class="setup-pairs"><div><dt>You set the outcome.</dt><dd>The lead plans the sprints and brings in teams.</dd></div><div><dt>You answer what only you can.</dt><dd>LGcode shows you where you are needed.</dd></div><div><dt>You approve what users would notice.</dt><dd>Teams commit and merge inside their own branches.</dd></div></dl><div class="setup-actions"><button class="primary" data-setup-go="found">Get started</button><a class="inline-link" href="?sample=small&from=setup${setupSearch()}">Look around first</a></div>`}
function setupHarnessRow(h,nothingInstalled){const sub=subscriptionItems.find(a=>a.id===h.accountId),state=!h.installed?'<span class="setup-state">Not installed</span>':sub?.status==='Available'?`<span class="setup-state ready">${icon('check')}Signed in</span>`:`<button class="secondary" data-setup-sign-in="${h.accountId}">Sign in</button>`;return `<li><div class="setup-row-text"><strong>${esc(harnessLabels[h.harness])}</strong>${h.version?`<small>${esc(h.version)}</small>`:''}${nothingInstalled?`<code>${esc(h.install)}</code>`:''}</div>${state}</li>`}
function setupFound(){
 const back='<button class="secondary" data-setup-go="welcome">Back</button>',mark=setupStepMark(2);
 if(setupScanning||!setupScan)return `${mark}<h1 id="setup-title" tabindex="-1">Found on this computer</h1><p class="setup-note" role="status">Looking at ${esc(thisMachine.name)}…</p><div class="setup-actions">${back}</div>`;
 if(setupScan.failure)return `${mark}<h1 id="setup-title" tabindex="-1">Found on this computer</h1><p class="error" role="alert">${esc(setupScan.failure)}</p><div class="setup-actions">${back}<button class="primary" data-setup-rescan>Try again</button></div>`;
 const {harnesses,repositories:found,folder}=setupScan,installed=harnesses.some(h=>h.installed),ready=subscriptionItems.some(a=>a.status==='Available'&&a.enabled!==false);
 const shown=found.slice(0,5),folderRow=setupChangingFolder?`<form id="setup-folder-form" class="setup-folder"><label for="setup-folder-input">Folder</label><input id="setup-folder-input" value="${esc(folder)}" required spellcheck="false"><div class="setup-folder-actions"><button class="primary">Look here</button><button class="secondary" type="button" data-setup-folder-cancel>Cancel</button></div></form>`:'';
 return `${mark}<h1 id="setup-title" tabindex="-1">Found on this computer</h1><p class="setup-note">LGcode only looked. Nothing here has changed.</p>
 <section class="setup-section" aria-labelledby="setup-harnesses"><div class="setup-section-head"><h2 id="setup-harnesses">Harnesses</h2><button class="secondary dense" data-setup-rescan>Check again</button></div><ul class="setup-rows">${harnesses.map(h=>setupHarnessRow(h,!installed)).join('')}</ul></section>
 <section class="setup-section" aria-labelledby="setup-repositories"><div class="setup-section-head"><h2 id="setup-repositories">Repositories in ${esc(folder)}</h2><button class="secondary dense" data-setup-folder>Change folder</button></div>${folderRow}${shown.length?`<ul class="setup-rows">${shown.map(r=>`<li><div class="setup-row-text"><strong>${esc(r.name)}</strong><small>${esc(r.branch)}</small></div><span class="setup-state">${esc(r.age)}</span></li>`).join('')}</ul>${found.length>shown.length?`<p class="setup-note">And ${found.length-shown.length} more.</p>`:''}`:'<p class="setup-note">None in this folder. The next step can start a new one.</p>'}</section>
 ${ready?'':`<p class="setup-note" role="status">${installed?'The project lead needs a harness that is signed in.':'The project lead needs a harness. Install one, then check again.'}</p>`}
 <div class="setup-actions">${back}<button class="primary" data-setup-go="project" ${ready?'':'disabled'}>Continue</button></div>`;
}
function placeSetupForm(){
 const form=$('#project-form'),leave=form.querySelector('footer [data-close="project-dialog"]');
 $('#setup-slot').append(form);
 if(leave){leave.removeAttribute('data-close');leave.dataset.setupBack='';leave.textContent='Back'}
 prepareProjectForm(setupScan.repositories[0]?.id||'__new');
 setupNameEdited=false;nameFromRepository();
 setupFormReady=true;
}
function nameFromRepository(){if(setupNameEdited||!$('#setup-slot').contains($('#project-form')))return;const repoName=repositories.find(r=>r.id===$('#project-repo').value)?.name||'',words=repoName.replace(/[-_]+/g,' ');$('#project-name').value=words?words[0].toUpperCase()+words.slice(1):'';updateProjectLocation()}
$('#project-name').addEventListener('input',()=>{setupNameEdited=true});
$('#project-repo').addEventListener('change',nameFromRepository);
function finishSetup(){
 if(!api.setup.needed()&&!$('#setup-slot').contains($('#project-form')))return;
 const form=$('#project-form'),back=form.querySelector('[data-setup-back]');
 if(back){delete back.dataset.setupBack;back.dataset.close='project-dialog';back.textContent='Cancel'}
 $('#project-dialog').append(form);
 api.setup.finish();$('#setup').hidden=true;$('.app').hidden=false;
}
function runSetupScan(folder){
 setupScanning=true;setupChangingFolder=false;setupFormReady=false;
 api.setup.scan(folder).then(result=>{setupScan=result;setupScanning=false;if(api.setup.needed()&&sampleSession==='owner')renderSetup()});
}
function renderSetup(){
 $('.app').hidden=true;$('#auth-gate').hidden=true;$('#setup').hidden=false;
 if(setupPage!=='welcome'&&!setupScan&&!setupScanning)runSetupScan();
 const usable=setupScan&&!setupScan.failure&&!setupScanning&&subscriptionItems.some(a=>a.status==='Available'&&a.enabled!==false),page=setupPage==='project'&&!usable?'found':setupPage;
 if(page==='project'){
  api.setup.adopt(setupScan.repositories);
  if(!setupFormReady)placeSetupForm();
  $('#setup-body').innerHTML=`${setupStepMark(3)}<h1 id="setup-title" tabindex="-1">First project</h1>`;
 }else $('#setup-body').innerHTML=page==='welcome'?setupWelcome():setupFound();
 $('#setup-slot').hidden=page!=='project';
}
function showSetupPage(page){if(page!=='welcome')api.setup.advance(page);setupPage=page;renderSetup();$('#setup-title')?.focus({preventScroll:true});$('#setup').scrollTop=0}
$('#setup').addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.setupGo)showSetupPage(d.setupGo);
 else if('setupBack' in d)showSetupPage('found');
 else if('setupRescan' in d){setupScan=null;runSetupScan();renderSetup()}
 else if('setupFolder' in d){setupChangingFolder=true;renderSetup();$('#setup-folder-input').select()}
 else if('setupFolderCancel' in d){setupChangingFolder=false;renderSetup()}
 else if(d.setupSignIn)openSignIn(subscriptionItems.find(a=>a.id===d.setupSignIn));
 else if(b.id==='setup-log-out'){try{sessionStorage.removeItem('lgcode-session')}catch{}endSampleSession('')}
});
$('#setup').addEventListener('submit',e=>{if(e.target.id!=='setup-folder-form')return;e.preventDefault();const folder=$('#setup-folder-input').value.trim();if(!folder)return;setupScan=null;runSetupScan(folder);renderSetup()});
$('#subscription-login').addEventListener('close',()=>{if(api.setup.needed()&&sampleSession==='owner'){renderSetup();$('#setup-title')?.focus({preventScroll:true})}});

// Stages and mocks. A project moves through stage-named teams. One with screens to draw gets a Mocks tab,
// where the screens are the repository's own code running on invented data.
const stageOrder=['design','plan','build','review','handover'],stageNames={design:'Design',plan:'Plan',build:'Build',review:'Review',handover:'Hand over'};
const embedded=window.top!==window,mocksReads=H.mocksReads;
function stageStrip(project=p()){if(!project.stage)return '';const steps=stageOrder.filter(s=>s!=='design'||project.mocks),at=steps.indexOf(project.stage);return `<ol class="stage-strip" aria-label="Project stage">${steps.map((s,i)=>`<li class="${i<at?'done':i===at?'current':''}" ${i===at?'aria-current="step"':''}>${i<at?icon('check'):''}${esc(stageNames[s])}</li>`).join('')}</ol>`}
const mocksPanes=new Map(),serverStates=new Map(),repoTabs=new Map(),designEdits=new Set();
let mockFrame=null,approvingProject=null;
function mocksPane(project=p()){if(!mocksPanes.has(project.id))mocksPanes.set(project.id,{pane:'screens',screenId:null,size:mobile.matches?'phone':'desktop',edit:false,scenario:project.mocks.scenarios[0]?.id||null});const s=mocksPanes.get(project.id);if(!project.mocks.screens.some(x=>x.id===s.screenId))s.screenId=project.mocks.screens[0]?.id||null;return s}
const agentName=id=>{const project=id&&agentProject(id);return project?findAgent(id,project).name:'LGcode'};
const designTeam=(project=p())=>project.teams.find(t=>t.stage==='design');
function openMocks(pid=state.projectId){const project=projects.find(x=>x.id===pid);if(!project?.mocks)return;expandedRepos.add(project.repoId);expandedProjects.add(pid);go({repoId:project.repoId,projectId:pid,view:'mocks',teamId:null,agentId:project.lead.id,tab:'chat',sprintId:null,taskId:null},project.workspace)}
function mockUrl(project,screen){const source=project.mocks.source,route=screen.route.replace('{sample}',mocksPane(project).scenario||'small');return source._tag==='server'?`${location.protocol}//${location.hostname}:${source.port}${route}`:route}
function mocksView(){
 const project=p(),m=project.mocks,s=mocksPane(),panes=[['screens','Screens',m.screens.length],['data','Data',m.data.length],['components','Components',m.components.length]];
 const toolbar=`<div class="mocks-toolbar"><div class="segmented" role="group" aria-label="Mocks view">${panes.map(([id,label,n])=>`<button data-mocks-pane="${id}" aria-pressed="${s.pane===id}">${label}<small>${n}</small></button>`).join('')}</div>${m.approvedAt?`<p class="mocks-approved">${icon('check')}Approved</p>`:`<button class="primary" id="approve-mocks" ${m.screens.length&&canOperate()?'':'disabled'}>Approve mocks</button>`}</div>`;
 return stageStrip()+toolbar+(s.pane==='data'?mocksData():s.pane==='components'?mocksComponents():mocksScreens());
}
function mocksScreens(){
 const project=p(),m=project.mocks,s=mocksPane(),screen=m.screens.find(x=>x.id===s.screenId),drawer=designTeam()?.agents.at(-1)?.name||project.lead.name;
 if(!screen)return emptyState(`${esc(drawer)} is drawing the first screen.`);
 const changing=pending.has(conversationKey()),server=m.source._tag==='server',stopped=server&&serverStates.get(project.id)==='stopped';
 const list=`<nav class="mock-screen-list" aria-label="Screens">${m.screens.map(x=>`<button data-mock-screen="${esc(x.id)}" aria-current="${x.id===screen.id}"><strong>${esc(x.title)}</strong><small>${changing&&x.id===screen.id?'Changing…':'Revision '+x.revisions.length}</small></button>`).join('')}</nav>`;
 const bar=`<div class="mock-frame-bar">${s.edit?'':`<div class="segmented" role="group" aria-label="Frame size">${[['phone','Phone'],['desktop','Desktop']].map(([id,label])=>`<button data-mock-size="${id}" aria-pressed="${s.size===id}">${label}</button>`).join('')}</div>`}${m.scenarios.length&&!s.edit?`<label class="mock-scenario">Data<select id="mock-scenario">${m.scenarios.map(x=>`<option value="${esc(x.id)}" ${x.id===s.scenario?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label>`:''}<button class="secondary" id="mock-edit" aria-pressed="${s.edit}">${s.edit?'Done editing':'Edit design'}</button></div>`;
 const stage=s.edit?pencilCanvas(project.repoId,m.designFile,screen.title):stopped?`<div class="mock-stopped" role="status"><h2>The mocks are not running</h2><p>LGcode runs them from the repository with this command.</p><code>${esc(m.source.command)}</code><button class="secondary" id="mock-check-server">Check again</button></div>`:embedded?`<div class="design-canvas" role="img" aria-label="${esc(screen.title)}"><strong>${esc(screen.title)}</strong></div>`:`<div class="mock-stage" id="mock-stage"><div class="mock-device" id="mock-slot" data-size="${s.size}"></div></div>`;
 const history=`<section class="mock-history" aria-label="Changes to ${esc(screen.title)}"><h2>Changes</h2><ol>${[...screen.revisions].reverse().slice(0,6).map(r=>`<li><span>${esc(r.summary)}</span><small>${esc(agentName(r.by))} · ${timeOf(r)}</small></li>`).join('')}</ol></section>`;
 return `<div class="mocks-screens">${list}<div class="mock-main">${bar}${stage}<p class="mock-note">${esc(screen.note)}</p>${history}</div></div>`;
}
const screenTitles=(m,ids)=>ids.map(id=>esc(m.screens.find(s=>s.id===id)?.title||id)).join(', ');
function mocksData(){
 const project=p(),m=project.mocks,rows=m.data.map(d=>({...d,...api.mocks.field(project.repoId,d)})),changes=rows.filter(r=>r.status!=='matches').length;if(!rows.length)return emptyState('The data appears with the first screen.');
 return `<p class="detail-summary">${m.scenarios.length?`The screens run on invented data: ${m.scenarios.map(x=>esc(x.label)).join(' or ')}.`:'The screens run on invented data.'} ${changes?`${plural(changes,'change')} to the schema ${changes===1?'goes':'go'} to the Planning team when you approve.`:'Every field the screens need is already in the schema.'}</p><div class="compact-table-wrap"><table class="compact-table mock-data-table" aria-label="Data the screens need"><thead><tr><th>Field</th><th>Type</th><th>Used on</th><th>Schema</th></tr></thead><tbody>${rows.map(r=>`<tr><td><code>${esc(r.entity)}.${esc(r.field)}</code></td><td>${esc(r.type)}</td><td>${screenTitles(m,r.screens)}</td><td><span class="schema-state ${r.status}">${r.status==='new'?'New':r.status==='differs'?'Schema has '+esc(r.known):'Matches'}</span></td></tr>`).join('')}</tbody></table></div>`;
}
function mocksComponents(){
 const m=p().mocks,drafts=m.components.filter(c=>c.origin==='draft').length,label={real:'Real',draft:'Draft',promoted:'Moved in'};if(!m.components.length)return emptyState('The components appear with the first screen.');
 return `<p class="detail-summary">The screens use the repository’s real components. ${drafts?`${plural(drafts,'new component')} ${drafts===1?'stays a draft':'stay drafts'} until you approve, then ${drafts===1?'moves':'move'} into the real components.`:'Nothing new was drawn.'}</p><div class="compact-table-wrap"><table class="compact-table mock-component-table" aria-label="Components the screens use"><thead><tr><th>Component</th><th>Status</th><th>Lives in</th><th>Used on</th></tr></thead><tbody>${m.components.map(c=>`<tr><td>${esc(c.name)}</td><td><span class="component-state ${c.origin}">${label[c.origin]}</span></td><td><code>${esc(c.path)}</code></td><td>${screenTitles(m,c.screens)}</td></tr>`).join('')}</tbody></table></div>`;
}
const repoTab=()=>repoTabs.get(state.repoId)||'projects';
const repoTabsHtml=tab=>`<div class="segmented repo-tabs" role="group" aria-label="Repository views">${[['projects','Projects'],['design','Design']].map(([id,label])=>`<button data-repo-tab="${id}" aria-pressed="${tab===id}">${label}</button>`).join('')}</div>`;
function designView(){
 const d=api.mocks.design(state.repoId),edit=designEdits.has(state.repoId),moved=projects.filter(x=>x.repoId===state.repoId&&x.mocks).flatMap(x=>x.mocks.components.filter(c=>c.origin==='promoted').map(c=>({...c,from:x.name})));
 if(!d&&!moved.length)return emptyState('No design until a project’s mocks are approved.');
 const file=d?.file||'design/'+repo().name+'.fig',head=`<div class="design-head"><p class="detail-summary">The components every project in ${esc(repo().name)} draws from, saved in <code>${esc(file)}</code>.</p><div class="segmented" role="group" aria-label="Design mode"><button data-design-mode="view" aria-pressed="${!edit}">View</button><button data-design-mode="edit" aria-pressed="${edit}">Edit</button></div></div>`;
 if(edit)return head+pencilCanvas(state.repoId,file,repo().name);
 const tokens=d?.tokens?.length?`<section class="design-section"><h2>Colors</h2><ul class="token-list">${d.tokens.map(t=>{const name=t.name||t,value=t.value||`var(${t})`;return `<li><span class="swatch" style="background:${esc(value)}"></span><code>${esc(name)}</code></li>`}).join('')}</ul></section>`:'';
 const rows=[...(d?.components||[]),...moved.map(c=>({name:c.name,path:c.path,variants:'From '+c.from}))];
 return head+tokens+`<section class="design-section"><h2>Components</h2><div class="compact-table-wrap"><table class="compact-table design-table" aria-label="Components"><thead><tr><th>Component</th>${rows.some(c=>c.preview)?'<th>Preview</th>':''}<th>Variants</th><th>Lives in</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${esc(c.name)}</td>${rows.some(x=>x.preview)?`<td><div class="component-preview" inert>${c.preview||''}</div></td>`:''}<td>${esc(c.variants||'')}</td><td><code>${esc(c.path)}</code></td></tr>`).join('')}</tbody></table></div></section>`;
}
// OpenPencil runs beside the service and opens the repository's design file. Its frame is kept
// between renders like the mock frame, so a render never throws away unsaved drawing.
const pencilStates=new Map();let pencilFrame=null;
function checkPencil(url){pencilStates.set(url,'checking');const controller=new AbortController();setTimeout(()=>controller.abort(),4000);fetch(url,{method:'HEAD',cache:'no-store',signal:controller.signal}).then(r=>r.ok?'ready':'missing',()=>'unreachable').then(result=>{pencilStates.set(url,result);remember();render()})}
function pencilCanvas(repoId,file,label){
 if(embedded)return `<div class="design-canvas pencil" role="img" aria-label="Design canvas for ${esc(label)}"><strong>OpenPencil</strong><code>${esc(file)}</code></div>`;
 const e=api.mocks.editor(repoId,file),st=pencilStates.get(e.file);
 if(!st)queueMicrotask(()=>pencilStates.has(e.file)||checkPencil(e.file));
 if(!st||st==='checking')return `<div class="design-canvas pencil" role="status"><strong>Opening OpenPencil</strong><code>${esc(file)}</code></div>`;
 if(st==='unreachable')return `<div class="mock-stopped pencil" role="status"><h2>OpenPencil is not reachable</h2><p>Start it on this computer with this command, then open <a href="${esc(e.base)}/" target="_blank" rel="noopener">${esc(e.base)}</a> once and accept its certificate.</p><code>docker compose -f design/openpencil/compose.yml up -d</code><button class="secondary" data-pencil-check="${esc(e.file)}">Check again</button><p class="op-caption">It will open <code>${esc(file)}</code>.</p></div>`;
 const src=st==='ready'?`${e.base}/?file=${encodeURIComponent(e.file)}`:`${e.base}/`;
 return `<div class="pencil">${st==='missing'?`<p class="op-caption"><code>${esc(file)}</code> does not exist yet, so OpenPencil starts an empty document.</p>`:''}<div class="pencil-slot" id="pencil-slot" data-src="${esc(src)}" data-label="${esc(label)}"></div></div>`;
}
function mountPencilFrame(){
 const slot=$('#pencil-slot');if(!slot){if(pencilFrame?.el.isConnected&&!pencilFrame.el.closest('#view-body'))pencilFrame.el.remove();return}
 if(pencilFrame?.src!==slot.dataset.src){pencilFrame?.el.remove();const el=document.createElement('iframe');el.className='pencil-frame';el.title='OpenPencil: '+slot.dataset.label;el.allow='clipboard-read; clipboard-write; local-fonts';el.src=slot.dataset.src;pencilFrame={el,src:slot.dataset.src}}
 if(document.body.moveBefore&&pencilFrame.el.isConnected)slot.moveBefore(pencilFrame.el,null);else slot.append(pencilFrame.el);
}
// The frame keeps its page between renders where the browser can move it without reloading.
function parkMockFrame(){for(const el of [mockFrame?.el,pencilFrame?.el])if(el?.isConnected&&document.body.moveBefore)document.body.moveBefore(el,null)}
function mockCss(screen){return screen.revisions.map(r=>r.css).filter(Boolean).join('\n')}
function styleMockFrame(){const el=mockFrame?.el;if(!el)return;try{const doc=el.contentDocument;if(!doc?.head)return;let style=doc.getElementById('mock-revisions');if(!style){style=doc.createElement('style');style.id='mock-revisions';doc.head.append(style)}style.textContent=mockCss(mockFrame.screen)}catch{}}
function fitMockFrame(){const slot=$('#mock-slot'),stage=$('#mock-stage');if(!slot||!stage||!mockFrame)return;const [w,h]=mocksReads.devices[slot.dataset.size],scale=Math.min(1,stage.clientWidth/w);slot.style.width=w*scale+'px';slot.style.height=h*scale+'px';Object.assign(mockFrame.el.style,{width:w+'px',height:h+'px',transform:`scale(${scale})`})}
function mountMockFrame(){
 const slot=$('#mock-slot');if(!slot){if(mockFrame?.el.isConnected&&!mockFrame.el.closest('#view-body'))mockFrame.el.remove();return}
 const project=p(),screen=project.mocks.screens.find(x=>x.id===mocksPane().screenId),url=mockUrl(project,screen),key=project.id+'/'+screen.id+'/'+url;
 if(mockFrame?.key!==key){mockFrame?.el.remove();const el=document.createElement('iframe');el.title=screen.title;el.src=url;el.addEventListener('load',styleMockFrame);mockFrame={el,key,screen,seen:screen.revisions.length}}
 mockFrame.screen=screen;
 if(document.body.moveBefore&&mockFrame.el.isConnected)slot.moveBefore(mockFrame.el,null);else slot.append(mockFrame.el);
 fitMockFrame();styleMockFrame();
 if(screen.revisions.length>mockFrame.seen){mockFrame.seen=screen.revisions.length;if(project.mocks.source._tag==='server')mockFrame.el.src=url;const stage=$('#mock-stage');stage.classList.add('updated');setTimeout(()=>stage.classList.remove('updated'),1400)}
 if(project.mocks.source._tag==='server'&&!serverStates.has(project.id))checkMockServer(project);
}
function checkMockServer(project){serverStates.set(project.id,'checking');const source=project.mocks.source,controller=new AbortController();setTimeout(()=>controller.abort(),4000);fetch(`${location.protocol}//${location.hostname}:${source.port}/`,{mode:'no-cors',signal:controller.signal}).then(()=>'up',()=>'stopped').then(result=>{const was=serverStates.get(project.id);serverStates.set(project.id,result);if(result!==was&&state.view==='mocks'&&state.projectId===project.id){if(result==='up')mockFrame=null;remember();render()}})}
new ResizeObserver(()=>fitMockFrame()).observe($('#view-body'));
function openApproveMocks(){const project=p(),m=project.mocks,drafts=m.components.filter(c=>c.origin==='draft').length,changes=m.data.filter(d=>api.mocks.field(project.repoId,d).status!=='matches').length;approvingProject=project.id;$('#approve-mocks-title').textContent='Approve the mocks for '+project.name+'?';$('#approve-mocks-content').innerHTML=`<p>The ${plural(m.screens.length,'screen')} become the design that the code must match.</p><ul><li>${plural(drafts,'draft component')} ${drafts===1?'moves':'move'} into the real components.</li><li>${plural(changes,'schema change')} ${changes===1?'becomes a task':'become tasks'}.</li><li>Each screen gets a task to wire it to real data.</li></ul><p>A Planning team turns these into the first sprint.</p>`;$('#approve-mocks-dialog').showModal()}
const previousMocksRender=render;
render=function(){parkMockFrame();previousMocksRender();if(sampleSession!=='owner'||api.setup.needed())return;gateConnection();
 if(state.view==='mocks'&&!p()?.mocks){openBoard();return}
 if(state.view==='mocks'){const m=p().mocks;$('#participants').innerHTML=`${esc(designTeam()?.name||'Design team')} · ${plural(m.screens.length,'screen')} · ${m.approvedAt?'Approved':'Not approved yet'}`}
 mountMockFrame();mountPencilFrame();
};
let mocksRenderQueued=false;
